  "rootCause": "Design: 重构过程中缺乏行为等价性验证与契约测试机制，导致枚举值变更未同步更新测试断言与集成触发逻辑。",
  "violatedPrinciples": [
    {
      "principleId": "contract-stability-01",
      "title": "状态机重构契约稳定性原则",
      "rationale": "核心状态枚举（stage）的变更未同步更新下游测试断言与集成触发条件，破坏了行为等价承诺。"
    }
  ],
  "evidence": [
    {
      "sourceRef": "owner_reported:cli",
      "note": "No session context available"
    },
    {
      "sourceRef": "diagnosis_manual_1781079251251_llyt4bto",
      "note": "PRI-363 重构后 pain.test.ts 出现行为回归：stage 枚举值从 gate_admitted/triage_evidence_only 改为 trigger_rejected，导致2条现有测试断言失败；auto-entry-gate 集成测试 TC2 中 repeated failures 不再触发诊断，emitSync 未被调用，行为等价承诺破裂"
    }
  ],
  "recommendations": [
    {
      "kind": "principle",
      "description": "建立重构行为等价性验证原则，确保状态机变更不破坏现有测试契约。",
      "abstractedPrinciple": "重构必须保持对外行为契约不变，任何状态枚举变更需同步更新测试断言与集成触发逻辑。"
    },
    {
      "kind": "rule",
      "description": "当检测到 stage 枚举值或核心诊断触发函数发生变更时，自动拦截并执行回归检查。",
      "triggerPattern": "(stage|emitSync).*=(trigger_rejected|gate_admitted)",
      "action": "强制运行 pain.test.ts 与 auto-entry-gate TC2，验证行为等价性承诺。"
    },
    {
      "kind": "implementation",
      "description": "更新 pain.test.ts 中的断言以适配 trigger_rejected 枚举值；在 auto-entry-gate TC2 的 repeated failures 路径中恢复 emitSync 调用逻辑。"
    },
    {
      "kind": "prompt",
      "description": "在执行代码重构后，必须主动验证所有相关单元测试与集成测试的行为等价性，确保状态流转与副作用触发符合原有契约。"
    }
  ],
  "confidence": 0.85,
  "ambiguityNotes": [
    "CLI提交缺乏主机会话溯源，完整对话轨迹不可用",
